script:
frappe.ui.form.on('Quality Review', {
	refresh(frm) {
		frm.set_query('goal', () => {
		    return {
				filters: {
					'service': frm.doc.service
				}
			};
		});
	}
});

frappe.ui.form.on('Task', {
	refresh(frm) {
        if(frm.doc.matter) {
            frappe.db.get_value('Matter', frm.doc.matter, 'matter_type', (r) => {
                frm.set_query('type', () => {
                    return {
                        filters: {
                            'matter_type': r.matter_type
                        }
                    };
                });
            });   
        }
	},
	type: function(frm) {
        frappe.db.get_value('Task Type', frm.doc.type, 'description', (r) => {
            if (r && r.description) {
                frm.set_value('subject', r.description);
            }
        });
	}
});

frappe.ui.form.on('Timesheet', {
	refresh(frm) {
		frm.set_query('matter', () => {
			if (frm.doc.customer) {
				return {
					filters: { 'customer': frm.doc.customer }
				};
			}
		});

		frm.set_query('case', () => {
			if (frm.doc.customer) {
				return {
					filters: { 'customer': frm.doc.customer }
				};
			}
		});
	}
});

frappe.ui.form.on('Issue', {
	refresh(frm) {
		frm.set_query("custom_matter", () => {
		    if(frm.doc.customer) {
		        return {
					filters: {
						'customer': frm.doc.customer
					}
				};
		    }
		});
	},
	issue_type: function(frm) {
        if (!frm.doc.subject) {
            frm.set_value("subject", frm.doc.issue_type);
        }
    }
});
